import 'dart:convert';

/// Shared, versioned Unicode table generated by Python. No OS locale dependence.
class TextNormalizer {
  TextNormalizer.fromJson(String data)
      : replacements = (jsonDecode(data)['replacements'] as Map<String, dynamic>)
            .map((key, value) => MapEntry(int.parse(key), value as String));
  final Map<int, String> replacements;
  String call(String text) => text.runes
      .map((cp) => replacements[cp] ?? String.fromCharCode(cp))
      .join();
}

/// Flutter text selections use UTF-16; source intervals use Unicode code points.
int toCodePointOffset(String text, int utf16Offset) {
  if (utf16Offset < 0 || utf16Offset > text.length) {
    throw RangeError.range(utf16Offset, 0, text.length);
  }
  return text.substring(0, utf16Offset).runes.length;
}

int toUtf16Offset(String text, int codePointOffset) =>
    String.fromCharCodes(text.runes.take(codePointOffset)).length;
